export const PROVINCE_BY_SLUG: Record<string, Province> = Object.fromEntries(
  PROVINCES.map((p) => [p.slug, p]),
);

/** Hub slug for a province, e.g. `percetakan/cetak-buku/jawa-timur`. */
export const PROVINCE_HUB_PREFIX = "percetakan/cetak-buku/";

export function provinceHubSlug(provinceSlug: string): string {
  return `${PROVINCE_HUB_PREFIX}${provinceSlug}`;
}

/** Province slug for a generated city page slug suffix, if known. */
export function provinceOfCityKey(cityKey: string): string | undefined {
  return CITY_PROVINCE[cityKey];
}
